# A module-level cache: results are stored here keyed by n so we never recompute.
_cache = {}

def fib(n):
    if n in _cache:
        return _cache[n]
    if n == 0:
        result = 0
    elif n == 1:
        result = 1
    else:
        result = fib(n - 1) + fib(n - 2)
    _cache[n] = result
    return result

print(fib(10))
